<dialog x-ref="extractionPlanDialog" class="w-full max-w-lg rounded-xl border border-stone-200 bg-white p-5 text-stone-900 shadow-xl dark:border-stone-700 dark:bg-stone-900 dark:text-stone-100" @click="if($event.target===$el)$el.close()">
<h2 class="font-serif text-xl">Existing extraction plans</h2><p class="mt-2 text-sm">Edit a saved plan for <strong x-text="visual?.name"></strong>, or create a new plan from its current image and pickup areas.</p>
<label class="field mt-4">Saved plan<select x-model="extractionPlanChoice"><template x-for="b in sceneExtractions" :key="b.id"><option :value="b.id" x-text="'Extraction #'+b.id+' · '+b.outputs.length+' outputs'"></option></template></select></label>
<div class="mt-5 flex flex-wrap justify-end gap-2"><button type="button" class="btn-secondary" @click="$refs.extractionPlanDialog.close()">Cancel</button><button type="button" class="btn-secondary" @click="chooseExtractionPlan(false)">Create new plan</button><button type="button" class="btn-primary" :disabled="!extractionPlanChoice" @click="chooseExtractionPlan(true)">Edit existing plan</button><button type="button" class="btn-primary" :disabled="!extractionPlanChoice" @click="updateExtractionPlan()">Update with new areas</button></div>
</dialog>
<dialog x-ref="extractionDialog" class="extraction-dialog rounded-xl border border-stone-200 bg-white text-stone-900 shadow-xl dark:border-stone-700 dark:bg-stone-900 dark:text-stone-100" @cancel="if(extractionBusy)$event.preventDefault();else clearInterval(extractionTimer)" @click="if($event.target===$el && !extractionBusy)closeExtraction()">
<div class="flex h-full min-h-0 flex-col">
<header class="flex shrink-0 items-center justify-between gap-3 border-b p-3 dark:border-stone-700"><h2 class="font-serif text-xl" x-text="extractionMode==='switches'?'Create switches':'Extract collectible items'"></h2><button class="btn-secondary" type="button" @click="closeExtraction()" :disabled="extractionBusy">Close</button></header>
<div class="min-h-0 flex-1 space-y-5 overflow-y-auto p-4">
<div x-show="extractionProgress" x-cloak role="status" aria-live="polite" class="flex items-center gap-3 rounded-lg border border-amber-300 bg-amber-50 p-3 text-sm text-amber-950 dark:border-amber-800 dark:bg-amber-950 dark:text-amber-100"><span x-show="extractionPreparing" class="h-5 w-5 shrink-0 animate-spin rounded-full border-2 border-current border-t-transparent motion-reduce:animate-none" aria-hidden="true"></span><span x-text="extractionProgress"></span></div>
<p x-show="extractionError" x-text="extractionError" class="text-sm text-red-600 dark:text-red-400" role="alert"></p>
<div x-show="!extractionBatch" class="space-y-3">
<label x-show="extractionMode==='collectibles'" class="field">Background removal references<select x-model="extractionReferenceMode" :disabled="extractionPreparing"><option value="original_and_annotated">Original + numbered reference (2 images)</option><option value="annotated_only">Numbered reference only (1 image)</option></select></label>
<template x-if="asset(extractionSource)"><div class="relative mx-auto max-w-3xl"><img :src="asset(extractionSource).url" class="w-full rounded" alt="Original scene"><template x-for="a in extractionAreas.filter(a=>a.selected)" :key="a.id"><div class="pointer-events-none absolute border-2 border-amber-400 bg-amber-300/10" :style="style(a.bounds)"><span class="bg-black/80 px-1 text-xs text-white" x-text="a.label"></span></div></template></div></template>
<div class="grid grid-cols-2 gap-3 lg:grid-cols-3"><template x-for="a in extractionAreas" :key="a.id"><div class="overflow-hidden rounded-xl border border-stone-300 dark:border-stone-700" :class="a.selected?'ring-1 ring-amber-500':''">
<div class="relative flex h-44 items-center justify-center bg-stone-100 p-2 dark:bg-stone-950"><canvas x-effect="drawExtractionCrop($el,a.bounds,extractionSource)" :aria-label="'Cropped preview of '+a.label" class="max-h-full max-w-full object-contain"></canvas><button type="button" class="image-zoom-button" :aria-label="'Enlarge crop of '+a.label" @click="$dispatch('vsg-image',{url:$el.parentElement.querySelector('canvas').toDataURL('image/png'),name:a.label})"><x-zoom-icon /></button></div>
<label class="flex items-start gap-2 p-3 text-sm"><input type="checkbox" class="mt-1 shrink-0" x-model="a.selected" :disabled="extractionPreparing || a.reused"><span><span class="block font-semibold" x-text="a.label"></span><span x-show="a.reused" class="block text-xs">Existing outputs will be reused.</span><span x-show="extractionMode==='collectibles' && !a.eligible" class="block text-xs text-amber-700 dark:text-amber-300">Will create and link a new Inventory item.</span></span></label>
<label x-show="extractionMode==='collectibles' && !a.reused" class="field p-3">Source area<select x-model="a.initial_empty" @change="a.initial_empty=$event.target.value==='true'" :disabled="extractionPreparing"><option :value="false">Contains the item — extract it</option><option :value="true">Empty — place the linked inventory item</option></select></label>
</div></template></div>
<p x-show="!extractionAreas.length" class="text-sm">Choose the matching v2 click action on your scene areas first.</p><button type="button" class="btn-primary" :disabled="extractionBusy || extractionPreparing || !extractionAreas.some(a=>a.selected)" :aria-busy="extractionPreparing" @click="prepareExtraction()" x-text="extractionPreparing?'Preparing…':'Prepare extraction plan'"></button>
</div>
<template x-if="extractionBatch"><div class="space-y-5">
<label class="field">Image-edit model<select x-model="extractionModel"><option value="">Choose a model</option><template x-for="m in models" :key="m.id"><option :value="m.id" x-text="imageModelLabel(m)"></option></template></select></label>
<button type="button" class="btn-primary" :disabled="extractionBusy || extractionRun || !extractionModel || !extractionMissing.length" @click="generateMissingExtraction()" x-text="extractionRun?'Submitting…':'Generate all unaccepted outputs'"></button>
<p class="text-sm">Completed renders are accepted automatically. Unaccept any result to try again, then activate to apply the replacements to the scene.</p>
<section class="w-full space-y-3" aria-label="Extraction image comparison">
<div class="inline-flex gap-1 rounded-lg border border-stone-300 p-1 dark:border-stone-700" role="group" aria-label="Preview image">
<button type="button" class="rounded-md px-3 py-2 text-sm" :class="extractionPreview==='original'?'bg-stone-800 text-white dark:bg-stone-200 dark:text-stone-900':''" :aria-pressed="extractionPreview==='original'" @click="extractionPreview='original'">Original</button>
<button type="button" class="rounded-md px-3 py-2 text-sm" :class="extractionPreview==='composition'?'bg-stone-800 text-white dark:bg-stone-200 dark:text-stone-900':''" :aria-pressed="extractionPreview==='composition'" @click="extractionPreview='composition'">Accepted composition</button>
</div>
<div class="relative w-full overflow-hidden rounded"><img :src="asset(extractionPreview==='original'?extractionBatch.source_asset_id:(extractionBackground || extractionBatch.source_asset_id))?.url" class="block h-auto w-full" :alt="extractionPreview==='original'?'Original scene preserved':'Accepted composition preview'"><template x-for="o in extractionLayers.filter(o=>!extractionHidden.includes(o.id))" :key="o.id"><img x-show="extractionPreview==='composition'" :src="asset(o.accepted_asset_id)?.url" :style="style(o.bounds)" class="pointer-events-none absolute" alt="Scene item layer"></template></div>
<div x-show="extractionPreview==='composition'" class="flex flex-wrap gap-3"><template x-for="o in extractionLayers" :key="o.id"><label class="flex items-center gap-1 text-xs"><input type="checkbox" :checked="!extractionHidden.includes(o.id)" @change="extractionHidden=$event.target.checked?extractionHidden.filter(id=>id!==o.id):[...extractionHidden,o.id]"><span x-text="o.name"></span></label></template></div>
</section>
<template x-for="o in extractionBatch.outputs" :key="o.id"><section class="space-y-3 rounded-xl border border-stone-300 p-4 dark:border-stone-700">
<div class="flex items-center justify-between"><h3 class="font-semibold" x-text="o.name"></h3><span class="text-xs" x-text="o.accepted_asset_id?(o.reused?'Accepted · reused':'Accepted'):extractionPending(o)?'Generating':o.jobs?.some(j=>j.status==='completed')?'Not accepted':'Ready to generate'"></span></div>
<div x-show="o.type==='background'" class="flex flex-wrap items-end gap-3"><label class="field min-w-0 flex-1">Background removal references<select :value="o.reference_mode||'original_and_annotated'" :disabled="extractionBusy || extractionRun || extractionPending(o)" @change="extractionAction(o,'references',null,$event.target.value)"><option value="original_and_annotated">Original + numbered reference (2 images)</option><option value="annotated_only">Numbered reference only (1 image)</option></select></label><button type="button" class="btn-secondary" :disabled="extractionBusy || extractionRun || extractionPending(o)" @click="extractionAction(o,'references')">Refresh numbered reference</button></div>
<button type="button" x-show="o.accepted_asset_id && o.type!=='switch_off'" class="text-sm underline" :disabled="extractionBusy || extractionRun" @click="extractionAction(o,'unaccept')">Unaccept and try again</button>
<div class="flex gap-3"><template x-for="ref in o.references" :key="ref"><button type="button" @click="$dispatch('vsg-image',asset(ref))"><img :src="asset(ref)?.url" class="h-24 w-32 rounded object-contain" alt="Generation reference"></button></template><label class="field flex-1">Prompt<textarea :readonly="o.type==='switch_off'" :value="extractionPrompts[o.id]??o.prompt" @input="extractionPrompts[o.id]=$event.target.value" rows="3" maxlength="10000"></textarea></label></div>
<div x-show="o.type!=='switch_off'" class="flex flex-wrap items-center gap-2"><button type="button" class="btn-primary" @click="extractionAction(o,'generate')" :disabled="extractionBusy || extractionRun || !extractionModel || extractionPending(o)">Generate new version</button><span x-show="extractionPending(o)" class="text-sm animate-pulse">Generating…</span></div>
<div class="flex flex-wrap gap-3"><template x-for="job in o.jobs" :key="job.id"><div class="w-48 space-y-2 rounded border border-stone-300 p-2 dark:border-stone-700"><p class="text-xs" x-text="'Version '+(o.jobs.indexOf(job)+1)+' · '+job.status"></p><p x-show="job.error" x-text="job.error" class="text-xs text-red-600 dark:text-red-400"></p><template x-for="id in job.asset_ids" :key="id"><div class="space-y-2"><button type="button" class="extraction-checker w-full rounded" @click="$dispatch('vsg-image',asset(id))"><img :src="asset(id)?.url" class="h-32 w-full object-contain" alt="Generated candidate"></button><button type="button" class="btn-secondary w-full" :disabled="extractionBusy || o.accepted_asset_id===id" @click="extractionAction(o,'accept',id)" x-text="o.accepted_asset_id===id?'Accepted':'Accept version'"></button></div></template></div></template></div>
</section></template>
</div></template>
</div><footer x-show="extractionBatch" class="shrink-0 border-t p-3 dark:border-stone-700"><p class="mb-2 text-xs">Activation updates only the selected v2 areas. Collectibles use a clean background and removable layers; switches toggle between local patches. Original full-scene pickup and state-change actions are left unchanged.</p><button type="button" class="btn-primary" :disabled="extractionBusy || extractionRun || Object.keys(extractionBounds).length>0 || !extractionBatch?.outputs.every(o=>o.accepted_asset_id)" @click="activateExtraction()">Activate accepted results in scene</button></footer>
</div></dialog>
